fast_pseudocode:
@triton.autotune(configs=[Config({'XBLOCK': 256, 'R0_BLOCK': 128}, ...), ...], key=[...])
@triton.jit
def kernel(...):
    ...

# CORRECT: grid uses meta to pick up the autotuned XBLOCK
grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](arg_0, arg_1, xnumel, r0_numel)
